/// <reference types="vite/client" />
import "./guide-style.css";
import { parseAdvice, renderGuide, type GuideOut } from "./guide-view";

// guide.json is generated by `pnpm guide ideal`; falls back to the sample fixture.
const real = Object.values(import.meta.glob("./data/guide.json", { eager: true, import: "default" }))[0] as GuideOut | undefined;
const sample = Object.values(import.meta.glob("./data/guide.sample.json", { eager: true, import: "default" }))[0] as GuideOut;
document.getElementById("guide")!.innerHTML =
  (real ? "" : `<p class="banner">sample data: run <code>pnpm guide ideal</code> to generate the real guide</p>`) + renderGuide(real ?? sample);

document.getElementById("advice")!.innerHTML =
  `<textarea id="advice-text" rows="6" placeholder="Paste advice JSON"></textarea><button id="advice-go">Show advice</button><div id="advice-out"></div>`;
document.getElementById("advice-go")!.addEventListener("click", () => {
  const out = document.getElementById("advice-out")!;
  try { out.innerHTML = renderGuide(parseAdvice((document.getElementById("advice-text") as HTMLTextAreaElement).value)); }
  catch (e) { out.innerHTML = `<p class="warn"></p>`; out.firstElementChild!.textContent = (e as Error).message; }
});
